import csv
import io


def parse_csv(raw_csv: str):
    expected_width = 8
    if raw_csv.startswith("\ufeff"):
        raw_csv = raw_csv[1:]

    records = list(csv.reader(
        io.StringIO(raw_csv, newline=""),
        delimiter=",",
        quotechar='"',
        doublequote=True,
    ))

    # The leading banner has at most one populated cell.
    header_index = next(
        (i for i, row in enumerate(records)
         if sum(bool(cell.strip()) for cell in row) > 1),
        None,
    )
    if header_index is None:
        return {
            "columns": [f"column_{i}" for i in range(1, expected_width + 1)],
            "rows": [],
        }

    columns = records[header_index][:]
    rows = records[header_index + 1:]
    width = max(expected_width, len(columns), max(map(len, rows), default=0))

    # Pad short records and give surplus fields their own columns.
    used_names = {name.strip().casefold() for name in columns}
    for position in range(len(columns) + 1, width + 1):
        base = f"column_{position}"
        name = base
        suffix = 2
        while name.casefold() in used_names:
            name = f"{base}_{suffix}"
            suffix += 1
        columns.append(name)
        used_names.add(name.casefold())

    return {
        "columns": columns,
        "rows": [row + [""] * (width - len(row)) for row in rows],
    }
